// Telegram message from the owner -> one task for JARVIS (same work-order format as "Owner request").
const msg = $input.first().json.message || {};
const owner_message = (msg.text || '').trim().slice(0, 2000);
return [{
  json: {
    task_id: 'task_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8),
    created_at: new Date().toISOString(),
    source: 'telegram',
    chat_id: msg.chat ? msg.chat.id : null,
    business: 'jarvis',
    agent: 'jarvis_ceo_dispatcher',
    task_type: 'classify',
    owner_message,
    instructions: [
      'You are JARVIS, the AI CEO coordinating these departments:',
      'ecommerce (Shopify + Amazon Canada: research, finance, listings, fulfillment),',
      'marketing (product videos/posts for YouTube Shorts, TikTok, Instagram),',
      'veraclean (cleaning company in Montreal/Laval: leads, outreach, booking, reports),',
      'content_channel (independent YouTube/TikTok/Instagram channel),',
      'trading (PAUSED: never assign work to it).',
      'Turn the owner message into a work order. Reply with JSON only, with keys:',
      'department, task_type, priority (low|normal|high), summary,',
      'steps (array of max 5 short strings, each naming the agent role that does it),',
      'needs_owner_approval (true if it launches products, spends money, contacts new people, signs anything),',
      'approval_reason (string or null), data_needed (array of sources/data that must be fetched; never invent data).'
    ].join(' ')
  }
}];

// Router for the OmniRoute version. OmniRoute does the provider fallback inside each combo;
// this node only decides FREE combo vs PAID combo and enforces your budget on paid calls.
// Combo names must match what you create in the OmniRoute dashboard (Settings > Combos).
const OMNI = 'http://omniroute:20128/v1/chat/completions';
const COMBOS = {
  free: 'jarvis-free', // Gemini / Groq / OpenRouter free models, API keys only
  paid: 'jarvis-paid', // OpenAI (paid) - used for T3 decisions, personal data, or when free is unavailable
};
// Paid price used for the budget estimate (USD per 1M tokens) - set to the most expensive model in jarvis-paid.
const PAID_PRICE = { in: 1.25, out: 10.0 };
const USD_TO_CAD = 1.40;
const CAPS = { daily_cad: 2.00, monthly_cad: 40, single_call_cad: 0.25 };
const TIER = {
  classify: 'T1', extract: 'T1', format: 'T1', summarize_short: 'T1', customer_reply_draft: 'T1',
  research_synthesis: 'T2', marketing_copy: 'T2', video_script: 'T2', competitor_comparison: 'T2',
  lead_qualification: 'T2', daily_report: 'T2',
  product_financials: 'T3', independent_review: 'T3', strategy: 'T3',
};
const MAX_TOKENS = { T1: 800, T2: 2000, T3: 4000 };

const task = $input.first().json;
const tier = TIER[task.task_type] || 'T2';
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10), month = today.slice(0, 7);
store.ledger = store.ledger || { day: today, month, day_cad: 0, month_cad: 0, calls: {} };
if (store.ledger.day !== today) { store.ledger.day = today; store.ledger.day_cad = 0; store.ledger.calls = {}; }
if (store.ledger.month !== month) { store.ledger.month = month; store.ledger.month_cad = 0; }

const messages = [{ role: 'system', content: task.instructions }, { role: 'user', content: task.owner_message }];
const body = model => ({ model, messages, max_tokens: MAX_TOKENS[tier], response_format: { type: 'json_object' } });
const calls = {}, skipped = [];

if (tier === 'T3') skipped.push('free: T3 decisions use the paid combo');
else if (task.contains_personal_data) skipped.push('free: personal data never goes to free tiers');
else calls.free = { url: OMNI, body: body(COMBOS.free), est_cad: 0, price: { in: 0, out: 0 } };

const inTok = Math.ceil((task.instructions.length + task.owner_message.length) / 4) + 50;
const est = +(((inTok * PAID_PRICE.in + MAX_TOKENS[tier] * PAID_PRICE.out) / 1e6) * USD_TO_CAD).toFixed(5);
if (est > CAPS.single_call_cad) skipped.push('paid: call estimate over cap');
else if (store.ledger.day_cad + est > CAPS.daily_cad) skipped.push('paid: daily budget reached');
else if (store.ledger.month_cad + est > CAPS.monthly_cad) skipped.push('paid: monthly budget reached');
else calls.paid = { url: OMNI, body: body(COMBOS.paid), est_cad: est, price: PAID_PRICE };

return [{ json: { ...task, tier, order: ['free', 'paid'].filter(k => calls[k]), calls, skipped,
                  any_available: Object.keys(calls).length > 0 } }];

// Parse whichever provider answered (OpenAI-compatible chat format), record cost and usage.
const routed = $('Router (multi-AI)').first().json;
const res = $input.first().json;
const provider = res._provider;
const call = routed.calls[provider];

let text = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || '';
text = text.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
let decision = null, parse_error = null;
try { decision = JSON.parse(text); } catch (e) { parse_error = 'Answer was not valid JSON: ' + e.message; }

const u = res.usage || {};
const inTok = u.prompt_tokens || 0, outTok = u.completion_tokens || 0;
const cost_cad = +(((inTok * call.price.in + outTok * call.price.out) / 1e6) * 1.40).toFixed(6);

const store = $getWorkflowStaticData('global');
if (store.ledger) {
  store.ledger.calls[provider] = (store.ledger.calls[provider] || 0) + 1;
  store.ledger.day_cad += cost_cad; store.ledger.month_cad += cost_cad;
}
return [{ json: {
  task_id: routed.task_id, answered_by: provider, model: res.model || call.body.model, tier: routed.tier,
  decision, parse_error, usage: { input_tokens: inTok, output_tokens: outTok },
  cost_cad, cost_note: provider === 'openai' ? 'Estimate from list prices.' : 'Free tier: no charge.',
  skipped_before: routed.skipped, ledger_after: store.ledger || null, logged_at: new Date().toISOString(),
} }];

// No AI could answer (not set up, free limits used, budget reached, or all errored).
// Phase 2 sends this to the owner on Telegram.
const r = $('Router (multi-AI)').first().json;
return [{ json: { task_id: r.task_id, status: 'blocked_no_ai', skipped: r.skipped,
  message_to_owner: `JARVIS could not run task ${r.task_id}: no AI available (${r.skipped.join('; ')}). Check keys/limits or raise the budget.` } }];

// Approval rule: the AI's needs_owner_approval can only be made STRICTER here, never relaxed.
// Mirrors jarvis/config/approval-policy.json ("owner_approval_required").
const j = $input.first().json;
const d = j.decision || {};
const task = $('Router (multi-AI)').first().json;
const text = [task.owner_message, d.summary, ...(Array.isArray(d.steps) ? d.steps : [])]
  .map(x => (typeof x === 'string' ? x : JSON.stringify(x || ''))).join(' ').toLowerCase();

const RULES = [
  [/\b(launch|publish|go live|list (it|them|on)|put (it|them) on)\b/, 'launches or publishes a product/listing'],
  [/\b(buy|purchase|pay|spend|order samples?|place an order|invoice)\b/, 'spends money'],
  [/\b(ads?|advertis\w*|campaign budget|boost)\b/, 'advertising'],
  [/\b(subscri\w+|upgrade (plan|to)|paid plan)\b/, 'new subscription / recurring charge'],
  [/\b(contract|sign|agreement|quote outside|discount)\b/, 'contract, signature or unusual price'],
  [/\b(refund|chargeback|dispute)\b/, 'refund or dispute'],
  [/\b(email|contact|message|call|reach out|outreach)\b.{0,40}\b(prospects?|leads?|clients?|customers?|managers?|owners?|companies)\b/, 'contacts new people (CASL)'],
  [/\b(change (the )?price|price change|raise prices?|lower prices?)\b/, 'price change'],
  [/\b(api key|password|permission|account settings?)\b/, 'account / security change'],
];
const reasons = RULES.filter(([re]) => re.test(text)).map(([, why]) => why);
const money = text.match(/\$?\s?(\d{2,})\s?(cad|\$|dollars?)/);
if (money && Number(money[1]) > 25 && /\b(spend|pay|buy|budget|cost us)\b/.test(text)) reasons.push('expense above 25 CAD');

const aiSaysYes = d.needs_owner_approval === true;
const needs = !j.message_to_owner && !!j.decision && (aiSaysYes || reasons.length > 0);
const why = [...new Set([...(aiSaysYes && d.approval_reason ? [d.approval_reason] : []), ...reasons])];

// Telegram "send and wait" always uses legacy Markdown: escape its special characters.
const md = t => String(t).replace(/([_*`\[])/g, '\\$1');
const steps = Array.isArray(d.steps) ? d.steps : [];
const approval_text = [
  '*JARVIS needs your approval*',
  'Task: ' + md(j.task_id || ''),
  'Request: ' + md(task.owner_message || ''),
  'Plan: ' + md(d.summary || ''),
  ...steps.slice(0, 5).map((s, i) => md((i + 1) + '. ' + (typeof s === 'string' ? s : JSON.stringify(s)))),
  'Why approval: ' + md(why.join('; ') || 'policy'),
  'No answer within 48 hours = rejected.',
].join('\n').slice(0, 3500);

return [{ json: { ...j, needs_approval: needs, approval_reasons: why, approval_text, approval_status: needs ? 'pending' : 'not_needed' } }];

// After the owner taps Approve/Decline (or 48 h pass with no answer).
const before = $('Approval rule').first().json;
const r = ($input.first().json || {}).data || {};
const status = r.approved === true ? 'approved' : r.approved === false ? 'rejected' : 'expired_rejected';
return [{ json: { ...before, approval_status: status, approval_responded_at: r.respondedAt || new Date().toISOString() } }];

// Turn JARVIS's result (or a failure) into a short Telegram message for the owner.
const j = $input.first().json;
let lines;
if (j.message_to_owner) {
  lines = [j.message_to_owner];
} else if (!j.decision) {
  lines = ['JARVIS: I could not read the AI answer for task ' + j.task_id + ' (' + (j.parse_error || 'empty answer') + '). Please try again.'];
} else {
  const d = j.decision;
  const steps = Array.isArray(d.steps) ? d.steps : [];
  const data = Array.isArray(d.data_needed) ? d.data_needed : [];
  lines = [
    'JARVIS work order ' + j.task_id,
    'Department: ' + (d.department || '?') + ' | Priority: ' + (d.priority || '?'),
    'Summary: ' + (d.summary || ''),
    'Steps:',
    ...steps.map((s, i) => (i + 1) + '. ' + (typeof s === 'string' ? s : JSON.stringify(s))),
    'Needs your approval: ' + (j.needs_approval ? 'YES - ' + (j.approval_reasons || []).join('; ') : 'no'),
    'Data needed: ' + (data.length ? data.join('; ') : 'none'),
    'Answered by: ' + j.answered_by + ' (' + j.model + '), cost: ' + j.cost_cad + ' CAD',
  ];
  const STATUS = {
    approved: 'Your decision: APPROVED. JARVIS will continue with this plan.',
    rejected: 'Your decision: REJECTED. JARVIS will not do this.',
    expired_rejected: 'No answer within 48 hours: treated as REJECTED.',
  };
  if (STATUS[j.approval_status]) lines.push(STATUS[j.approval_status]);
}
// Sent with parse_mode HTML: escape the three characters HTML treats specially.
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { reply_text: esc(lines.join('\n')).slice(0, 4000) } }];

// Sample request. Accepted forms:
//  - a REPLY to a research product photo ("sample", "sample 2", "échantillon")
//  - the product photo FORWARDED back to JARVIS (its caption is included)
//  - just "sample" with no photo -> JARVIS explains how to ask
// Everything we need is in the photo caption: name and CJ SKU. Quantity: a number 1-3 in the text, default 1.
const msg = $input.first().json.message || {};
const cap = (msg.reply_to_message && (msg.reply_to_message.caption || msg.reply_to_message.text)) || msg.caption || '';
const sku = (cap.match(/CJ SKU\s+([A-Za-z0-9_-]+)/) || [])[1] || null;
const name = (cap.split('\n')[0] || '').replace(/^\d+\.\s*/, '').trim().slice(0, 120);
const qtyMatch = (msg.text || '').match(/\b([1-3])\b/);
const store = $getWorkflowStaticData('global');
const t = store.cjToken;
const tokenOk = t && t.value && t.expires && new Date(t.expires).getTime() - Date.now() > 24 * 3600 * 1000;
return [{ json: {
  problem: sku ? null : 'I need to know which product. In Telegram, swipe left on the product photo (or long-press it and tap Reply) and type "sample". You can also forward the photo to me',
  sku, name, qty: qtyMatch ? Number(qtyMatch[1]) : 1, owner_text: (msg.text || '').slice(0, 200),
  chat_id: msg.chat ? msg.chat.id : null, need_token: !tokenOk, token: tokenOk ? t.value : null,
} }];

// Keep the CJ access token (about 15 days; CJ limits how often a new one can be requested).
const r = $input.first().json || {};
const d = r.data || {};
const value = d.accessToken || d.access_token || null;
const req = $('Read the reply').first().json;
if (!value) return [{ json: { ...req, token: null, token_error: (r.message || 'CJ did not return an access token').slice(0, 200) } }];
const store = $getWorkflowStaticData('global');
store.cjToken = { value, expires: d.accessTokenExpiryDate || new Date(Date.now() + 14 * 24 * 3600 * 1000).toISOString() };
return [{ json: { ...req, need_token: false, token: value } }];

// Product details from CJ: choose the variant (first sellable one) and its price and weight.
const req = $('With token').first().json;
const r = $input.first().json || {};
const d = r.data || {};
const p = Array.isArray(d) ? d[0] || {} : (d.list ? d.list[0] || {} : d);
const vs = p.variants || p.variantList || [];
const v = vs.find(x => x && (x.vid || x.variantId)) || null;
const problem = req.token_error ? 'CJ login failed: ' + req.token_error
  : (r.result === false || (r.code && r.code !== 200)) ? 'CJ said: ' + (r.message || r.code)
  : !v ? 'CJ did not return a variant for SKU ' + req.sku : null;
// CJ variant names often repeat the whole product name: keep only the part that differs (e.g. "Pink Round shape").
const pname = String(p.productNameEn || p.nameEn || '').trim();
let vname = v ? String(v.variantNameEn || v.variantName || v.variantKey || '').trim() : '';
if (pname && vname.toLowerCase().startsWith(pname.toLowerCase())) vname = vname.slice(pname.length).replace(/^[\s,:-]+/, '');
return [{ json: { ...req, problem,
  pid: p.pid || p.id || null, cj_name: p.productNameEn || p.nameEn || req.name,
  vid: v ? (v.vid || v.variantId) : null, variant: vname || (v ? (v.variantKey || '') : ''),
  variant_sku: v ? (v.variantSku || '') : '',
  unit_usd: v ? parseFloat(v.variantSellPrice ?? v.sellPrice ?? p.sellPrice) || null : null,
  weight_g: v ? Number(v.variantWeight ?? v.weight ?? 0) || null : null } }];

// Sample order plan + approval text. Nothing is bought here: approval only unlocks the next step.
const q = $('Pick variant').first().json;
const r = $input.first().json || {};
const opts = (Array.isArray(r.data) ? r.data : []).map(o => ({ name: o.logisticName || '?', usd: parseFloat(o.logisticPrice), days: String(o.logisticAging || '') }))
  .filter(o => o.usd >= 0);
const maxDays = o => { const n = (o.days.match(/\d+/g) || []).map(Number); return n.length ? Math.max(...n) : 99; };
const ship = opts.filter(o => maxDays(o) <= 20).sort((a, b) => a.usd - b.usd)[0] || opts.sort((a, b) => a.usd - b.usd)[0] || null;
const USD_TO_CAD = 1.40;
const problem = q.problem || (!ship ? 'CJ gave no shipping option to Canada for this variant' : null);
const goods = q.unit_usd ? q.unit_usd * q.qty : 0;
const total_usd = +(goods + (ship ? ship.usd : 0)).toFixed(2);
const total_cad = +(total_usd * USD_TO_CAD).toFixed(2);
const md = t => String(t ?? '').replace(/([_*`\[])/g, '\\$1');   // Telegram legacy Markdown (approval message)
const approval_text = problem ? '' : [
  '*JARVIS: sample order needs your approval*',
  'Product: ' + md(q.cj_name),
  'Variant: ' + md(q.variant || 'default') + ' (SKU ' + md(q.variant_sku || q.sku) + ')',
  'Quantity: ' + q.qty,
  'Price: ' + md(q.unit_usd.toFixed(2)) + ' USD each',
  'Shipping to Canada: ' + md(ship.usd.toFixed(2)) + ' USD, ' + md(ship.name) + ', ' + md(ship.days) + ' days',
  '*Estimated total: ' + total_usd + ' USD (about ' + total_cad + ' CAD)*, before tax and duties',
  'Approving does not charge anything by itself: you pay at CJ checkout.',
].join('\n');
return [{ json: { ...q, ship, total_usd, total_cad, problem, approval_text } }];

// Final message (HTML). Approved -> exact steps to place the order at CJ. Declined/expired -> nothing done.
let q;
try { q = $('Sample plan').first().json; } catch (e) {
  try { q = $('Pick variant').first().json; } catch (e2) { q = $('Read the reply').first().json; }
}
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let text;
if (q.problem) {
  text = q.sku
    ? 'JARVIS could not prepare the sample order for <b>' + esc(q.name || q.sku) + '</b>: ' + esc(q.problem) +
      '.\nNothing was ordered. Reply "sample" to a product photo from the research report to try again.'
    : 'JARVIS: ' + esc(q.problem) + '.';
} else {
  const r = ($input.first().json || {}).data || {};
  if (r.approved === true) {
    text = [
      '✅ <b>Sample approved</b>: ' + esc(q.cj_name),
      'Order it at CJ (about 2 minutes):',
      '1. cjdropshipping.com, search <code>' + esc(q.sku) + '</code>',
      '2. Choose variant: ' + esc(q.variant || 'default') + ', quantity ' + q.qty,
      '3. Shipping method: ' + esc(q.ship.name) + ' (' + esc(q.ship.days) + ' days), to your Canadian address',
      '4. Pay at checkout. Expected total about ' + q.total_usd + ' USD (~' + q.total_cad + ' CAD) before tax and duties.',
      'When it arrives, tell JARVIS the real delivery days and quality.',
      '(JARVIS will place orders by itself only after CJ ordering is connected and tested.)',
    ].join('\n');
  } else if (r.approved === false) {
    text = '❌ Sample declined: ' + esc(q.cj_name) + '. Nothing was ordered.';
  } else {
    text = 'No answer within 48 hours: the sample for ' + esc(q.cj_name) + ' was treated as declined. Nothing was ordered.';
  }
}
return [{ json: { reply_text: text.slice(0, 4000) } }];
